    "detail": "Противостояние между королем и парламентом в Англии привело к гражданской войне и переходу страны от абсолютистской формы правления к парламентской монархии. Важную роль в революционных событиях сыграли «новые дворяне». Так называлось мелкое и среднее дворянство, которое активно занималось торговой и предпринимательской деятельностью, в отличие от «старого дворянства» — землевладельцев феодального типа. В результате революции буржуазия получила доступ к государственной власти. Основная идея революции — равенство всех перед законом — оказала влияние на другие государства Европы.",
