    "detail": "Великобритания сознательно тормозила хозяйственное развитие своих американских колоний, в которых формировалось буржуазное общество. Это стало основной причиной стремления колонистов к независимости. 19 апреля 1775 г. началась вооруженная борьба колоний против Великобритании. Созданием американской регулярной армии руководил виргинский плантатор Дж. Вашингтон. В ходе войны за независимость на основе I 3 американских колоний было создано новое государство — Соединенные Штаты Америки. В США была принята конституция и установилась буржуазно-демократическая республика. Идеологической основой Войны за независимость были идеи Просвещения.",
