    "detail": "Неудачи в Ливонской войне царь Иван IV объяснял боярской «крамолой». С целью ее искоренения он разделил страну на две части. В одной сохранялась прежняя система управления во главе с Боярской думой. Другая часть — опричная — перешла под управление самого царя и лично преданных ему служилых людей — опричников. Эта реформа сопровождалась массовыми репрессиями (были казнены более 3 тыс. человек). Опричнина дала возможность Ивану IV безгранично усилить свою власть и завершить централизацию страны.",
