    "detail": "Революции 1848—1849 гг. произошли практически одновременно в крупнейших странах Европы. Они носили антифеодальный и национально-освободительный характер. Участники выступлений требовали демократизации общественной жизни, а также в зависимости от местных условий выдвигали лозунги национального объединения (Германия, Италия) или выделения из существовавших государств (Венгрия). Несмотря на широкое участие народных масс, ни в одной стране Западной Европы революции не завершились победой.",
