    "detail": "Война между Российской империей с одной стороны и коалицией в составе Великобритании, Франции, Османской империи и Сардинского королевства с другой. Боевые действия разворачивались на Кавказе, в Дунайских княжествах, на Балтийском, Черном, Азовском, Белом и Баренцевом морях, а также на Камчатке. Наибольшего напряжения они достигли в Крыму. Русские войска одержали ряд блистательных побед над турками. Но в итоге Россия потерпела поражение и временно утратила влияние в Черноморском бассейне.",
