    "detail": "В соответствии с договором Германия лишалась всех колоний: возвращала Франции Эльзас-Лотарингию и отдавала под управление союзников Саарскую область, передавала Бельгии округа Эйпен, Мальмеди и Моренэ, а Дании — Северный Шлезвиг. Германия признавала независимость Польши, Чехословакии, Австрии, Люксембурга. К Польше отходила значительная часть Померании, Познани, Западной и Восточной Пруссии, Верхней Силезии. Данциг (Гданьск) превращался в вольный город под управлением Лиги Наций. К Чехословакии отходила часть территории Силезии. Договор ограничивал численность немецкой армии до ТОО тыс. человек с запрещением производить тяжелое вооружение и строить крупные боевые корабли. Германия объявлялась единственной виновницей развязывания Первой мировой войны. На этом основании она должна была выплатить огромные репарации в пользу победителей. В итоге установленная сумма составила 132 млрд золотых марок.",
