    "summary": "В ночь на 7 ноября практически без всякого сопротивления вооруженные отряды солдат, рабочих и матросов (Красная гвардия) взяли под свой контроль важнейшие стратегические объекты Петрограда — вокзалы, мосты, телеграф, электростанцию.",
    "detail": "В ночь на 7 ноября практически без всякого сопротивления вооруженные отряды солдат, рабочих и матросов (Красная гвардия) взяли под свой контроль важнейшие стратегические объекты Петрограда — вокзалы, мосты, телеграф, электростанцию. С 7 на 8 ноября был взят Зимний дворец и арестовано Временное npaвительство. В это время в Смольном открылся II Всероссийский съезд Советов рабочих и солдатских депутатов. Депутаты от правого крыла партии эсеров и меньшевиков обвинили большевиков в путче и покинули заседание. Съезд, представленный большевиками и левыми эсерами, провозгласил переход власти к Советам в центре и на местах. Главными организаторами вооруженного восстания в Петрограде были В. И. Ленин, Л. Д. Троцкий, Я. М. Свердлов.",
