    "detail": "Основные этапы: * октябрь 1917 г. — май 1918 г. — война носила локальный характер; * июнь 1918 г. — июнь 1919 г. — эскалация войны летом — осенью 1918 г. и ожесточенная борьба регулярных красных и белых армий в декабре 1918 г. — июне 1919 г.; * июль 1919 г. — ноябрь 1920 г. — военный разгром белых армий; * декабрь 1920 г. — 1922 г. — завершение и ликвидация очагов гражданской войны на Дальнем Востоке, в Средней Азии и Закавказье. Основными силами гражданской войны были красные и белые. Красные были представлены большевиками и их сторонниками — большей частью пролетариата, беднейшего крестьянства и незначительной частью интеллигенции. Выступали они под лозунгом борьбы за ликвидацию буржуазных порядков, установление власти рабочих и крестьян в форме советов, строительство социализма и коммунизма. Белые объединяли все антибольшевистские силы — буржуазию, офицерство, зажиточное крестьянство, казачество, а также часть беднейших рабочих и крестьян, пострадавших от советской власти.",
