    "summary": "Острейшие социально-экономический и политический кризисы начала 1920-х гг.",
    "detail": "Острейшие социально-экономический и политический кризисы начала 1920-х гг. заставили большевистское руководство отказаться от политики военного коммунизма и перейти к новому курсу, который получил название новой экономической политики (нэп). Сущность нэпа заключалась в частичном восстановлении рыночной экономики, ее развитии на основе экономической заинтересованности и хозяйственного расчета при сохранении стратегической цели — построение социализма. Нэп стимулировал частную инициативу и содействовал оживлению экономики. К 1926 г. СССР достиг довоенного уровня в большинстве отраслей производства. Во второй половине 1920-х гг. началось вытеснение частного капитала государством и свертывание нэп.",
