    "detail": "В конце 1920-х гг. советское руководство во главе с И. В. Сталиным отказалось от продолжения нэпа и перешло к политике индустриализации, а затем и к коллективизации страны. СССР поставил задачу в короткий срок создать мощную индустриальную базу, опираясь на собственные силы. В тех исторических условиях эту задачу можно было решить только за счет усиления давления на крестьянство. В ходе сплошной коллективизации сельского хозяйства (создание колхозов и совхозов), начавшейся в конце 1929 г., был создан механизм перераспределения средств на нужды индустриализации. В течение первых трех пятилеток индустриализации (1928—1942)) экономика СССР добилась впечатляющих результатов, войдя в число четырех самых развитых стран мира (вместе с США, Германией и Великобританией).",
