    "summary": "Политика умиротворения, которую проводили Великобритания и Франция в отношении фашистской Германии, подталкивала советское руководство к сближению с Германией.",
    "detail": "Политика умиротворения, которую проводили Великобритания и Франция в отношении фашистской Германии, подталкивала советское руководство к сближению с Германией. 23 августа 1939 г. министр иностранных дел Германии И. фон Риббентроп и нарком иностранных дел СССР В. М. Молотов подписали в Москве Договор о ненападении между СССР и Германией и секретный дополнительный протокол к нему. Стороны договаривались не допустить военного столкновения между Германией и СССР и разграничивали «сферы государственных интересов». «Сферой интересов» Германии были признаны Западная и Центральная Польша и Литва, а СССР — территории, которых лишилась Россия в годы Первой мировой войны (Западная Украина, Западная Беларусь, Латвия, Эстония, Финляндия, Бессарабия). В этом же году были подписаны декларации о ненападении между Великобританией и Францией с одной стороны и гитлеровской Германией с другой.",
