    "summary": "В первые же дни Второй мировой войны руководство СССР опираясь на достигнутые с Германией соглашения о разделе сфер интересов, решило реализовать собственные военно-политические замыслы.",
    "detail": "В первые же дни Второй мировой войны руководство СССР опираясь на достигнутые с Германией соглашения о разделе сфер интересов, решило реализовать собственные военно-политические замыслы. Когда немецкие войска подступили к территории Западной Украины и Западной Беларуси, советское правительство отдало приказ Красной армии перейти советско-польскую границу и взять под защиту белорусское и украинское население. На территории Западной Беларуси и Западной Украины Красная армия выполняла свою освободительную миссию. Большая часть западноукраинского и западнобелорусского населения с радостью и надеждой встретила своих освободителей. В сентябре — октябре 1939 г. были заключены договоры о взаимопомощи с Прибалтийскими государствами — Эстонией, Латвией и Литвой.",
