    "detail": "Освободительная борьба турецкого народа за независимость, которую возглавил генерал Мустафа Кемаль. Ценой огромных жертв Кемалю удалось одержать победу над «халифатской армией» султана Мехмета VI и войсками интервентов. I ноября 1922 г. Великое национальное собрание Турции (ВНСТ) приняло закон об упразднении султаната. В апреле 1923 г. была создана новая политическая организация — Народная партия, позже переименованная в Народно-республиканскую партию (НРП). 23 октября 1923 г. Турция была провозглашена республикой. Этими актами завершился процесс слома старой политической системы и создания турецкого национального государства, получивший название Кемалистской революции.",
