    "title": "Национальная революция в Китае",
    "summary": "Национальная демократическая революция, в которой принимала участие Коммунистическая партия Китая (КПК), развивалась при поддержке СССР.",
    "detail": "Национальная демократическая революция, в которой принимала участие Коммунистическая партия Китая (КПК), развивалась при поддержке СССР. Она приняла форму Первой гражданской войны Юга Китая (блок КПК — Гоминьдан) против северных феодально-милитаристских клик. С помощью советских специалистов вооруженные силы Гоминьдана были реорганизованы в единую Национально-революционную армию (НРА). Сначала силами НРА были разгромлены гуандунские милитаристы. Затем начался Северный поход, которым завершилось объединение Китая под властью Гоминьдана.",
