    "detail": "Поход НРА Гоминьдана под руководством Чан Кайши из провинции Гуандун был направлен в союзе с коммунистами против северных милитаристов. Цель похода — вооруженным путем объединить Китай под властью Гоминьдана. Северный поход завершился разгромом армий северных милитаристов и объединением Китая. 12 апреля 1927 г. генерал Чан Кайши совершил переворот в Нанкине и Шанхае, разорвал союз с коммунистами и начал массовое истребление их сторонников. Договорившись с милитаристами и западными державами, он создал в Нанкине правительство Китайской Республики.",
