    "detail": "Встреча лидеров стран антигитлеровской коалиции — СССР США и Великобритании, посвященная установлению послевоенного мирового порядка и будущему разделу мира между странами-победительницами. И. В. Сталин, Ф. Д. Рузвельт и У. Черчилль приняли решение о послевоенной демилитаризации Германии, ликвидации ее вооруженных сил и военной промышленности, уничтожении на- цистской партии и наказании военных преступников, возмещении ущерба, нанесенного Германией союзникам в ходе войны, разделе Германии на оккупационные зоны. В ходе острых дискуссий была определена восточная граница Польши с учетом сохранения Западной Беларуси и Западной Украины в составе СССР На севере и западе Польша получала приращение территории за счет Германии. В обмен на вступление в войну с Японией после окончания войны в Европе СССР получал Курильские острова и Южный Сахалин, потерянный еще в Русско-японской войне.",
