    "detail": "В 1965 г. США перешли от военной помощи южновьетнамскому правительству к военным действиям против Демократической Ре- спублики Вьетнам. Американские ВВС совершали бомбардировки вьетнамской территории с применением специальных химических веществ, шариковых бомб и напалма. Во Вьетнаме воевали советские добровольцы — военные специалисты и летчики. В 1968 г. в Париже начались переговоры между ДРВ и США. Итогом четырехлетних переговоров стал выход США из войны в 19/3 г. В марте 1975 г. войска ДРВ начали масштабное наступление и заняли Южный Вьетнам. 2 июля 1976 г. была провозглашена Социалистическая Республика Вьетнам (СРВ). США потерпели поражение во Вьетнамской войне, в которой погибло более 58 тыс. американцев.",
