    "dateLabel": "29 июля – 15 октября 1946 г.",
    "kind": "event",
    "title": "Парижская мирная конференция",
    "summary": "Конференция, в которой участвовало 21 государство, рассмотрела проекты мирных договоров государств антигитлеровской коалиции с бывшими союзниками Германии в Европе — Италией, Болгарией, Венгрией, Румынией и Финляндией.",
    "detail": "Конференция, в которой участвовало 21 государство, рассмотрела проекты мирных договоров государств антигитлеровской коалиции с бывшими союзниками Германии в Европе — Италией, Болгарией, Венгрией, Румынией и Финляндией. Подписание мирных договоров состоялось ТО февраля 1947 г. В договорах констатировалось, что прекращается состояние войны со странами, подписавшими мир. Они обязаны были обеспечить демократические права и свободы граждан и выдать военных преступников. Мирные договоры зафиксировали территориальные изменения. Италия сохранялась в своих границах на I января 1938 г. Она теряла также все свои колонии. Небольшие районы территории Италии были переданы Франции. К Югославии перешла восточная часть Юлийской Крайны, Греция получила Додеканесские острова. Была выделена Свободная территория Триест, в 1954 г. поделенная между Италией и Югославией. Болгария восстанавливалась в границах на сентябрь 1940 г. Северная Трансильвания переходила от Венгрии к Румынии. Закарпатская Украина включалась в состав СССР. Советский Союз получал также область Петсамо (Печенга).",
