    "detail": "В июле — сентябре 1962 г. руководство СССР разместило на Кубе группу советских войск, оснащенную 42 ракетами с ядерными боеголовками. США потребовали удалить с острова советские ракеты и войска и вскоре установили «карантин» в отношении Кубы, т. е. фактическую морскую блокаду острова. Вооруженные силы США и СССР были приведены в полную боевую готовность. Возникла реальная угроза третьей мировой войны. В ходе обмена посланиями между Дж. Кеннеди и Н. С. Хрущевым было достигнуто компромиссное соглашение. Советское правительство обязалось демонтировать ракеты и вывезти их из Кубы. США дали обязательство не вторгаться на Кубу и через несколько месяцев удалили свои ракеты из Турции.",
